create table if not exists public.data_feature_events (id uuid primary key default gen_random_uuid(), subject_type text not null, subject_id uuid, actor_user_id uuid, business_id uuid, location_id uuid, fleet_vehicle_id uuid, event_type text not null, feature_code text, source_table text, source_id uuid, value_numeric numeric, value_text text, metadata jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now(), created_at timestamptz not null default now());
create index if not exists idx_dfe_subject on public.data_feature_events(subject_type,subject_id,occurred_at desc);
create index if not exists idx_dfe_feature on public.data_feature_events(feature_code,occurred_at desc);
create index if not exists idx_dfe_actor on public.data_feature_events(actor_user_id,occurred_at desc);
create index if not exists idx_dfe_business on public.data_feature_events(business_id,occurred_at desc);
create index if not exists idx_dfe_location on public.data_feature_events(location_id,occurred_at desc);
create table if not exists public.location_amenity_observations (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.locations(id) on delete cascade, user_id uuid, amenity_id uuid references public.amenities(id), status text not null check(status in ('present','absent','unknown')), confidence numeric, verification_method text, check_in_id uuid, photo_id uuid, notes text, observed_at timestamptz not null default now(), metadata jsonb not null default '{}'::jsonb);
create index if not exists idx_lao_location on public.location_amenity_observations(location_id,amenity_id,observed_at desc);
create table if not exists public.location_quality_observations (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.locations(id) on delete cascade, user_id uuid, check_in_id uuid, cleanliness_score numeric, accessibility_score numeric, safety_score numeric, availability_score numeric, condition_score numeric, overall_stars smallint check(overall_stars between 1 and 5), feedback text, photo_id uuid, observed_at timestamptz not null default now(), metadata jsonb not null default '{}'::jsonb);
create index if not exists idx_lqo_location on public.location_quality_observations(location_id,observed_at desc);
create table if not exists public.location_observation_votes (id uuid primary key default gen_random_uuid(), observation_id uuid not null references public.location_quality_observations(id) on delete cascade, user_id uuid not null, vote text not null check(vote in ('helpful','not_helpful')), created_at timestamptz not null default now(), unique(observation_id,user_id));
create table if not exists public.user_feature_entitlements (user_id uuid not null, feature_code text not null, tier_code text, enabled boolean not null default false, source text, updated_at timestamptz not null default now(), primary key(user_id,feature_code));
create table if not exists public.feature_catalog (feature_code text primary key, name text not null, category text not null, minimum_tier text, points_value integer, enabled boolean not null default true, configuration jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.feature_access_events (id uuid primary key default gen_random_uuid(), user_id uuid, feature_code text not null, outcome text not null check(outcome in ('allowed','locked','redirected','denied','error')), tier_code text, destination text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists idx_fae_user on public.feature_access_events(user_id,created_at desc);
create index if not exists idx_fae_feature on public.feature_access_events(feature_code,created_at desc);
create table if not exists public.fleet_operational_events (id uuid primary key default gen_random_uuid(), business_id uuid, vehicle_id uuid, driver_id uuid, route_id uuid, event_type text not null, event_value numeric, unit text, latitude double precision, longitude double precision, occurred_at timestamptz not null default now(), metadata jsonb not null default '{}'::jsonb);
create index if not exists idx_foe_business on public.fleet_operational_events(business_id,occurred_at desc);
create index if not exists idx_foe_vehicle on public.fleet_operational_events(vehicle_id,occurred_at desc);
create table if not exists public.user_engagement_daily (user_id uuid not null, day date not null, sessions integer not null default 0, searches integer not null default 0, map_views integer not null default 0, detail_views integer not null default 0, check_ins integer not null default 0, qr_check_ins integer not null default 0, reviews integer not null default 0, photos integer not null default 0, amenity_verifications integer not null default 0, helpful_votes integer not null default 0, routes integer not null default 0, points_earned bigint not null default 0, feature_events integer not null default 0, metadata jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now(), primary key(user_id,day));
create table if not exists public.location_feature_summary (location_id uuid primary key references public.locations(id) on delete cascade, verification_score numeric, confidence_score numeric, cleanliness_score numeric, accessibility_score numeric, safety_score numeric, overall_rating numeric, rating_count bigint not null default 0, review_count bigint not null default 0, check_in_count bigint not null default 0, qr_check_in_count bigint not null default 0, photo_count bigint not null default 0, amenity_observation_count bigint not null default 0, favorite_count bigint not null default 0, route_count bigint not null default 0, last_verified_at timestamptz, feature_vector jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
alter table public.data_feature_events enable row level security; alter table public.location_amenity_observations enable row level security; alter table public.location_quality_observations enable row level security; alter table public.location_observation_votes enable row level security; alter table public.user_feature_entitlements enable row level security; alter table public.feature_catalog enable row level security; alter table public.feature_access_events enable row level security; alter table public.fleet_operational_events enable row level security; alter table public.user_engagement_daily enable row level security; alter table public.location_feature_summary enable row level security;
create policy data_feature_events_insert_own on public.data_feature_events for insert to authenticated with check (actor_user_id is null or actor_user_id=auth.uid());
create policy data_feature_events_select_own on public.data_feature_events for select to authenticated using (actor_user_id=auth.uid());
create policy location_amenity_observations_insert_own on public.location_amenity_observations for insert to authenticated with check (user_id=auth.uid());
create policy location_amenity_observations_select_public on public.location_amenity_observations for select to authenticated using (true);
create policy location_quality_observations_insert_own on public.location_quality_observations for insert to authenticated with check (user_id=auth.uid());
create policy location_quality_observations_select_public on public.location_quality_observations for select to authenticated using (true);
create policy location_observation_votes_own on public.location_observation_votes for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy feature_catalog_read on public.feature_catalog for select to authenticated using (enabled=true);
create policy feature_access_events_own on public.feature_access_events for insert to authenticated with check (user_id=auth.uid());
create policy feature_access_events_select_own on public.feature_access_events for select to authenticated using (user_id=auth.uid());
create policy user_engagement_daily_own on public.user_engagement_daily for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy location_feature_summary_read on public.location_feature_summary for select to authenticated using (true);
